            }
          }
        }
      }
    }
  ],
  "$defs": {
    "repoRelative": {
      "type": "string",
      "minLength": 1,
      "pattern": "^(?!/)(?!.*(?:^|/)\\.\\.(?:/|$)).+$"
    }
