#!/usr/bin/env python3
"""C18 run-dev-graph-status read-only search: R1 query normalize -> R2 plan -> R3 report."""
from __future__ import annotations

import argparse
import hashlib
import json
import subprocess
import sys
from pathlib import Path

PLUGIN = Path("/Users/dm/dev/dev/個人開発/harness/plugins/dev-graph")
ALLOWED_FILTERS = {"id", "kind", "project", "domain", "status", "tag", "keyword"}
FILTER_TO_FIELD = {
    "id": "graph_node_id", "kind": "artifact_kind", "project": "project_id",
    "domain": "domain", "status": "status",
}

parser = argparse.ArgumentParser()
parser.add_argument("--repo-root", required=True)
parser.add_argument("--id")
parser.add_argument("--kind")
parser.add_argument("--project")
parser.add_argument("--domain")
parser.add_argument("--status")
parser.add_argument("--tag", action="append", default=[])
parser.add_argument("--tag-match", choices=("all", "any"), default="all")
parser.add_argument("--keyword")
args = parser.parse_args()

# --- C24: fix the caller root from the resolver receipt, never from cwd. ---
receipt = json.loads(subprocess.run(
    [sys.executable, str(PLUGIN / "scripts" / "resolve-repo-context.py"),
     "--repo-root", args.repo_root, "--mode", "read"],
    capture_output=True, text=True, check=True).stdout)
root = Path(receipt["repo_root"])
if Path(receipt["content_roots"]["repository"]).resolve() != root.resolve():
    raise SystemExit("C24 receipt repo_root does not match content_roots.repository")
graph_path = Path(receipt["local_state_paths"]["graph"])
config_path = Path(receipt["local_state_paths"]["config"])


def digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def content_digest() -> str:
    entries = {}
    for key, value in sorted(receipt["content_roots"].items()):
        if key == "repository":
            continue
        base = Path(value)
        if not base.is_dir():
            continue
        for item in sorted(base.rglob("*")):
            if item.is_file():
                entries[str(item.relative_to(root))] = digest(item)
    return hashlib.sha256(json.dumps(entries, sort_keys=True).encode("utf-8")).hexdigest()


before = {"graph": digest(graph_path), "config": digest(config_path), "content": content_digest()}

# --- R1: normalized read-only query, allowed filter fields only. ---
query = {
    "id": args.id, "kind": args.kind, "project": args.project, "domain": args.domain,
    "status": args.status, "tag": args.tag, "keyword": args.keyword,
    "tag_match_mode": args.tag_match,
}
active_filters = {key: value for key, value in query.items()
                  if key != "tag_match_mode" and value not in (None, [], "")}
unknown = set(active_filters) - ALLOWED_FILTERS
if unknown:
    raise SystemExit(f"query contains fields outside the allowed filter vocabulary: {sorted(unknown)}")

# --- C11: read-only validation gate before any search. ---
gate = subprocess.run(
    [sys.executable, str(PLUGIN / "scripts" / "validate-graph-schema.py"),
     "--graph", str(graph_path), "--repo-root", str(root)],
    capture_output=True, text=True)
gate_report = json.loads(gate.stdout) if gate.stdout else {"valid": False, "violations": [gate.stderr.strip()]}
if gate.returncode != 0 or not gate_report.get("valid"):
    print(json.dumps({"status": "failed", "reason": "C11 validation failed",
                      "exit_code": gate.returncode, "gate": gate_report}, ensure_ascii=False, indent=2))
    raise SystemExit(1)

graph = json.loads(graph_path.read_text(encoding="utf-8"))
nodes = graph["nodes"]
dependents_index: dict[str, list[str]] = {node["graph_node_id"]: [] for node in nodes}
for node in nodes:
    for dependency in node.get("depends_on", []):
        dependents_index.setdefault(dependency, []).append(node["graph_node_id"])

# --- R2/R3: AND across every filter; tag mode as declared. ---
def matches(node: dict) -> bool:
    for key, field in FILTER_TO_FIELD.items():
        wanted = active_filters.get(key)
        if wanted is not None and node.get(field) != wanted:
            return False
    tags = set(node.get("tags") or [])
    if args.tag:
        hit = tags.issuperset(args.tag) if args.tag_match == "all" else bool(tags & set(args.tag))
        if not hit:
            return False
    if args.keyword:
        haystack = json.dumps(node, ensure_ascii=False).lower()
        if args.keyword.lower() not in haystack:
            return False
    return True


results = []
for node in nodes:
    if not matches(node):
        continue
    results.append({
        "graph_node_id": node["graph_node_id"],
        "artifact_kind": node["artifact_kind"],
        "project_id": node["project_id"],
        "domain": node["domain"],
        "tags": node.get("tags", []),
        "file_path": node["file_path"],
        "status": node["status"],
        "closed_at": node.get("closed_at"),
        "depends_on": node.get("depends_on", []),
        "dependents": sorted(dependents_index.get(node["graph_node_id"], [])),
        "parent_feature": node.get("parent_feature"),
        "feature_package_id": node.get("feature_package_id"),
        "tracker_binding": node.get("tracker_binding"),
        "linkage": {
            "issue_linkage": node.get("issue_linkage"),
            "beads_linkage": node.get("beads_linkage"),
            "github_publication": node.get("github_publication"),
            "github_project_linkages": node.get("github_project_linkages", []),
            "pull_request_linkages": node.get("pull_request_linkages", []),
        },
        "tombstoned": node["status"] == "tombstoned",
    })

after = {"graph": digest(graph_path), "config": digest(config_path), "content": content_digest()}

print(json.dumps({
    "status": "ok",
    "query": {"filters": active_filters, "tag_match_mode": args.tag_match},
    "graph_revision": graph.get("graph_revision"),
    "validation": {"exit_code": gate.returncode, "valid": gate_report["valid"],
                   "violations": gate_report["violations"]},
    "result_count": len(results),
    "results": results,
    "digest_before": before,
    "digest_after": after,
    "read_only": before == after,
    "external_writes": 0,
}, ensure_ascii=False, indent=2))

